/**
 * @param {int32} a
 * @param {int32} b
 * @returns {int32}
 */
function idiv(a, b) {
  return a / b
}

/**
 * @param {string} s
 * @returns {number} the code unit count
 */
function width(s) {
  return s.length
}

/**
 * @typedef {Object} Point
 * @property {number} x
 * @property {number} y
 */

/** @param {Point} p */
function manhattan(p) {
  return p.x + p.y
}

/**
 * @callback Combine
 * @param {number} a
 * @param {number} b
 * @returns {number}
 */

/** @param {Combine} fn */
function run(fn) {
  return fn(10, 5)
}

/**
 * @template T
 * @param {T[]} arr
 * @returns {T}
 */
function firstOf(arr) {
  return arr[0]
}

/**
 * @param {...number} nums
 */
function total(nums: number[]) {
  let t = 0
  for (const n of nums) t += n
  return t
}

/** @param {number | string} v */
function kind(v) {
  return typeof v
}

/** @param {{name: string, age: number}} u */
function greet(u) {
  return u.name
}

/** @param {function(number): number} f */
function twice(f) {
  return f(f(3))
}
